const heritageThreats=[{id:"taj-mahal-pollution",siteName:"Taj Mahal",location:"Agra, Uttar Pradesh",category:"pollution",categoryLabel:"Air & Industrial Pollution",badgeClass:"badge-pollution",severity:"critical",severityLabel:"Critical Risk",description:"Industrial emissions, rubber factories, and diesel exhaust lead to airborne soot deposition, causing yellowing of the pristine white Makrana marble facade and acid rain degradation.",conservationEfforts:"Taj Trapezium Zone (TTZ) established restricting heavy industries, zero-emission electric vehicle corridors implemented, and periodic mud-pack natural clay treatments applied."},{id:"majuli-island-erosion",siteName:"Majuli River Island",location:"Brahmaputra Basin, Assam",category:"climate",categoryLabel:"Climate Change & Erosion",badgeClass:"badge-climate",severity:"critical",severityLabel:"Critical Risk",description:"The world's largest inhabited river island has shrunk from over 1,200 sq km in 1900 to under 350 sq km due to severe Brahmaputra seasonal monsoon floods and riverbank erosion, threatening 500-year-old Neo-Vaishnavite Satras.",conservationEfforts:"Geo-textile riverbank reinforcement, bamboo porcupine dams, and bio-engineering projects along vulnerable banks."},{id:"jaisalmer-fort-water",siteName:"Jaisalmer Golden Fort",location:"Jaisalmer, Rajasthan",category:"water",categoryLabel:"Water Seepage & Structure",badgeClass:"badge-water",severity:"high",severityLabel:"High Concern",description:"Modern piped water supply without adequate drainage in the living fort has caused water seepage into soft yellow sandstone foundations on Trikuta Hill, leading to partial bastion collapses.",conservationEfforts:"Comprehensive drainage overhaul by ASI, sewage pipe replacement, and heritage housing capacity regulations."},{id:"sundarbans-sea-level",siteName:"Sundarbans Cultural & Eco Landscape",location:"South 24 Parganas, West Bengal",category:"climate",categoryLabel:"Climate Change & Coastal Erosion",badgeClass:"badge-climate",severity:"critical",severityLabel:"Critical Risk",description:"Accelerated sea-level rise (over 3mm/year) and intensifying Bay of Bengal cyclones submerge tidal islands, destroy mangrove habitats, and salinize historic coastal shrines and indigenous fishing settlements.",conservationEfforts:"Mangrove afforestation drives, embankment strengthening, and community climate resilience monitoring."},{id:"golden-temple-sarovar",siteName:"Sri Harmandir Sahib Surroundings",location:"Amritsar, Punjab",category:"pollution",categoryLabel:"Air & Industrial Pollution",badgeClass:"badge-pollution",severity:"high",severityLabel:"High Concern",description:"Heavy vehicular traffic, generator fumes, and agricultural stubble burning lead to high PM2.5 levels that dull gold foil gilding on the temple dome and pollute the sacred Sarovar water.",conservationEfforts:"Pedestrianized marble plaza around shrine, 24/7 air quality monitoring stations, and electric auto-rickshaw zone."},{id:"humayun-tomb-urban",siteName:"Humayun's Tomb Area",location:"Nizamuddin, New Delhi",category:"encroachment",categoryLabel:"Urban Encroachment",badgeClass:"badge-encroachment",severity:"moderate",severityLabel:"Moderate Watch",description:"High-density urban development, illegal vertical expansion, and infrastructure construction encroach upon the historical buffer zone of the 16th-century Mughal mausoleum complex.",conservationEfforts:"Aga Khan Trust for Culture (AKTC) buffer zone revitalization, Sundar Nursery urban park creation, and strict municipal building height caps."},{id:"hampi-ruins-tourism",siteName:"Hampi Monumental Complex",location:"Vijayanagara, Karnataka",category:"tourism",categoryLabel:"Tourism Pressure & Vandalism",badgeClass:"badge-tourism",severity:"high",severityLabel:"High Concern",description:"Unregulated commercial tourism, foot-traffic strain on dry-masonry stone structures, and occasional vandalism of carved pillars threaten Vijayanagara archaeological ruins.",conservationEfforts:"Visitor capacity capping at main temples, digital e-ticketing, security monitoring, and relocation of commercial markets outside core zone."},{id:"shimla-colonial-hillside",siteName:"Shimla Heritage Zone",location:"Shimla, Himachal Pradesh",category:"climate",categoryLabel:"Climate Change & Erosion",badgeClass:"badge-climate",severity:"high",severityLabel:"High Concern",description:"Unplanned concrete construction on steep hill slopes combined with intense cloudbursts causes landslides that damage 19th-century British colonial timber-and-stone architecture like the Viceregal Lodge.",conservationEfforts:"State green zone building bans, slope stability mapping, and heritage structure retrofitting."},{id:"konark-coastal-erosion",siteName:"Konark Sun Temple Coast",location:"Puri, Odisha",category:"climate",categoryLabel:"Climate Change & Erosion",badgeClass:"badge-climate",severity:"moderate",severityLabel:"Moderate Watch",description:"Coastal proximity exposes chlorite and khondalite stone carvings to saline sea winds and frequent severe Eastern Seaboard cyclones, causing surface flaking.",conservationEfforts:"Chemical weather-proofing coats, shelterbelt tree planting along coastline, and sand-fill structural reviews."},{id:"chilika-lake-heritage",siteName:"Chilika Lake Fishing Shrines",location:"Ganjam/Puri, Odisha",category:"water",categoryLabel:"Water Seepage & Ecosystem",badgeClass:"badge-water",severity:"moderate",severityLabel:"Moderate Watch",description:"Siltation, changed salinity balances, and illegal aquaculture encroach upon traditional fishing villages and island temples within Asia's largest brackish lagoon.",conservationEfforts:"Sea-mouth desiltation by Chilika Development Authority (CDA) and eco-tourism fishing community guidelines."}];function getFilteredThreats(e="",a="all",t="all"){const i=e.toLowerCase().trim();return heritageThreats.filter(e=>{const r="all"===a||e.category===a,n="all"===t||e.severity===t,o=!i||e.siteName.toLowerCase().includes(i)||e.location.toLowerCase().includes(i)||e.description.toLowerCase().includes(i)||e.conservationEfforts.toLowerCase().includes(i);return r&&n&&o})}function renderThreatsGrid(){if("undefined"==typeof document)return;const e=document.getElementById("threats-grid");if(!e)return;const a=getFilteredThreats(document.getElementById("threat-search")?.value||"",document.getElementById("category-filter")?.value||"all",document.getElementById("severity-filter")?.value||"all");0!==a.length?e.innerHTML=a.map(e=>`\n        <div class="threat-card" data-id="${e.id}">\n            <div>\n                <div class="card-top">\n                    <span class="badge ${e.badgeClass}">${e.categoryLabel}</span>\n                    <span class="severity-pill severity-${e.severity}">${e.severityLabel}</span>\n                </div>\n                <h3>${e.siteName}</h3>\n                <p class="location-text">📍 ${e.location}</p>\n                <p class="threat-description">${e.description}</p>\n            </div>\n            <div class="conservation-box">\n                <strong>🛡️ Conservation & Protection:</strong>\n                <p>${e.conservationEfforts}</p>\n            </div>\n        </div>\n    `).join(""):e.innerHTML='\n            <div class="empty-state" style="grid-column: 1/-1; text-align: center; padding: 3rem; color: #8b949e;">\n                <p>No endangered heritage sites match your filter criteria.</p>\n            </div>\n        '}"undefined"!=typeof document&&document.addEventListener("DOMContentLoaded",()=>{renderThreatsGrid(),document.getElementById("threat-search")?.addEventListener("input",renderThreatsGrid),document.getElementById("category-filter")?.addEventListener("change",renderThreatsGrid),document.getElementById("severity-filter")?.addEventListener("change",renderThreatsGrid)}),"undefined"!=typeof module&&module.exports&&(module.exports={heritageThreats:heritageThreats,getFilteredThreats:getFilteredThreats});